# The 48-Hour Blackout: every shot, in order, with its spoken lines (script v1, OK'd by Pushpam 14 Nov 2026).
# Speaker keys map to Kokoro voices in tts.py. ("card" shots have no voice; dur in seconds.)
SHOTS = [
# ---------------- ACT 0: cold open ----------------
dict(id="S01", act=0, lines=[("N", "Friday, November thirteenth. Six minutes before the stock market closed. For only the third time this century, the United States stopped every plane in the country from taking off.")]),
dict(id="S02", act=0, lines=[("N", "And that wasn't even the first thing to break that week."),
    ("JIMMY", "My flight says cancelled. My email won't load. My bank app says try later. What is happening?"),
    ("AGENT", "Sir, I'd check your email, but..."), ("JIMMY", "Yours too?"), ("AGENT", "Mine too.")]),
dict(id="S03", act=0, lines=[("N", "In about forty-eight hours, America's email, America's skies and America's payroll all failed, one after another. No bombs. No hackers, as far as anyone can tell. So how do three of the biggest systems on earth fall over in the same two days? And why should you, sitting at home, care?")]),
dict(id="S04", act=0, lines=[("N", "To answer that, we have to go back one day. Thursday. Just before one in the afternoon. Chicago.")]),
# ---------------- ACT 1: three people + the inbox ----------------
dict(id="S05", act=1, card="Three People, Two Days", dur=3.0),
dict(id="S06", act=1, lines=[("N", "Quick heads up: the three people you're about to meet are made up. Everything that happens to them happened to real people this week. Nina, forty-one, runs a twelve-person accounting office in Chicago. Her business lives in one place: her inbox. Clients, invoices, deadlines. If Outlook is open, Nina is working.")]),
dict(id="S07", act=1, lines=[("N", "Jimmy, twenty-nine, is flying Phoenix to Philadelphia on Friday for his sister's wedding. He's the best man. He has the rings.")]),
dict(id="S08", act=1, lines=[("N", "And Carla, fifty-two, shift lead at a big-box store in Ohio. She clocks in, clocks out, books her days off and gets paid, through one app on her phone. Three people. Three systems. They've never met. By Saturday, all three will have the same bad week.")]),
dict(id="S09", act=1, card="Thursday, 1 PM", sub="The Inbox Goes Dark", dur=3.2),
dict(id="S10", act=1, lines=[("N", "Thursday, just before one p.m. Eastern. Microsoft's email system, the engine behind Outlook, starts failing. Not in one city. In the US, in Europe, across Asia-Pacific. More than seventy countries.")]),
dict(id="S11", act=1, lines=[("NINA", "Is it us?"), ("WENDELL", "It's not us."), ("NINA", "Is it the building?"), ("WENDELL", "It's not the building."), ("NINA", "Is it... Chicago?"), ("WENDELL", "It's... Earth.")]),
dict(id="S12", act=1, lines=[("N", "Hospitals in Britain's National Health Service lost some services. Air India rerouted its email. Millions of office workers stared at a little spinning circle. Microsoft first blamed a surge of traffic, and a part of its system that checks whether servers are healthy. Later it said the real cause was an issue during an earlier network capacity upgrade.")]),
dict(id="S13", act=1, lines=[("N", "Translation: they were making the pipes bigger, and a joint burst. Remember that, because it's going to come back.")]),
dict(id="S14", act=1, lines=[("N", "It wasn't a one-hour blip. Microsoft didn't say service was fully restored until Saturday. About two days."),
    ("NINA", "Who still has a fax?"), ("DOT", "My uncle."), ("NINA", "Is your uncle a client?"), ("DOT", "He is now.")]),
dict(id="S15", act=1, lines=[("N", "For a twelve-person firm in the year-end rush, two days without email is two days of invoices not sent. Which means money not coming in. Small delays in big systems become real dollars in small businesses.")]),
# ---------------- ACT 2: every plane sits down ----------------
dict(id="S16", act=2, card="Friday, 3:54 PM", sub="Every Plane Sits Down", dur=3.2),
dict(id="S17", act=2, lines=[("N", "Friday. Jimmy's at the gate. Boarding in twenty minutes. At three fifty-four p.m. Eastern, the Federal Aviation Administration does something it almost never does. It orders a nationwide ground stop. No departures. Anywhere.")]),
dict(id="S18", act=2, lines=[("AGENT", "Ladies and gentlemen, the F A A has stopped all departures across the United States."),
    ("JIMMY", "Just this airport?"), ("AGENT", "Across the United States."), ("JIMMY", "Like... my whole country?"),
    ("AGENT", "Your whole country, sir. The pretzel stand is still open.")]),
dict(id="S19", act=2, lines=[("N", "Here's what was happening behind the curtain. Air traffic controllers talk to planes, and to each other, over a private communications network. On Friday, parts of that network started dropping out. Patchy radio. Gaps in radar. When controllers can't reliably see or talk to planes, you don't let more planes into the sky.")]),
dict(id="S20", act=2, lines=[("N", "Planes already flying landed normally. But nothing new took off for about four hours and twenty minutes, until eight fifteen that night.")]),
dict(id="S21", act=2, lines=[("N", "The damage was huge. More than four thousand seven hundred flights cancelled on Friday alone, and around ten thousand delayed. Hundreds diverted. And because planes and crews were now in the wrong cities, the mess rolled into Saturday, with thousands more cancellations.")]),
dict(id="S22", act=2, lines=[("JIMMY", "No, I still have the rings. No, I'm not in Philadelphia. No, I can't drive, it's two thousand miles. Tell her to stall. I don't know, Dad, give a really long toast!")]),
dict(id="S23", act=2, lines=[("N", "For perspective. The first time America cleared its entire sky was September eleventh, two thousand one. The last nationwide stop of departures before this was January twenty twenty-three, when a corrupted file in a pilot-safety system halted takeoffs for about an hour and a half. This one was longer. Much longer.")]),
# ---------------- ACT 3: the router from 2003 ----------------
dict(id="S24", act=3, card="The Router From 2003", dur=3.0),
dict(id="S25", act=3, lines=[("N", "So what broke? Transportation Secretary Sean Duffy explained it the next day. The F A A has been swapping old copper phone lines for modern fiber. During that work, one router started flooding the routers around it. Duffy said the system was seeing over one thousand connection attempts every four to five seconds.")]),
dict(id="S26", act=3, lines=[("WENDELL", "Good news, buddy. You're getting fiber."), ("ROUTER", "Fiber? I was built in two thousand three. I eat copper."),
    ("WENDELL", "It's faster."), ("ROUTER", "Hello? Hello? Hello? Is anyone there? Hello? Hello?"),
    ("WENDELL", "That's one thousand hellos every five seconds.")]),
dict(id="S27", act=3, lines=[("N", "According to C B S News, the problem was limited to one model of Cisco router, made between two thousand one and two thousand six. Duffy blamed contract work by L3Harris, the F A A's long-time communications contractor. The F A A switched off the faulty function on about sixty of those routers across the country.")]),
dict(id="S28", act=3, lines=[("N", "Think about that. The machines guiding the busiest airspace on earth were partly running on routers older than the first iPhone. And this wasn't a surprise. In September, the Government Accountability Office, Congress's watchdog, warned about the F A A's ageing copper cables, some dating back to the nineteen sixties, and its slow progress replacing them.")]),
dict(id="S29", act=3, lines=[("GUS", "It says here: fix the old wires."), ("WENDELL", "We're working on it."), ("GUS", "This report is from September."),
    ("WENDELL", "We're working on it fast."), ("GUS", "There's a dinosaur on page two.")]),
dict(id="S30", act=3, lines=[("N", "Duffy's answer is money. He's asking Congress for fifty billion dollars in emergency funding to rebuild the air traffic control system. That's about a hundred and fifty dollars for every person in America. Hold on to that number. When governments spend fifty billion dollars, somebody receives fifty billion dollars. We'll get to who.")]),
# ---------------- ACT 4: payday + hackers ----------------
dict(id="S31", act=4, card="Friday, 5 PM", sub="Payday Goes Missing", dur=3.2),
dict(id="S32", act=4, lines=[("N", "While Jimmy is sleeping on an airport floor, there's a third failure. Shortly after five p.m. on Friday, Workday starts going down. Most people have never heard of Workday. But if you work for a big company, there's a good chance it's how you get paid.")]),
dict(id="S33", act=4, lines=[("N", "Workday runs H R and payroll for around eleven thousand five hundred businesses, including names like Walmart, Target, General Electric and Morgan Stanley. Workers couldn't clock in or out, couldn't request time off, couldn't do benefits enrollment. Which, in November, is exactly when a lot of people pick next year's health insurance.")]),
dict(id="S34", act=4, lines=[("DOT", "How do I clock out?"), ("CARLA", "You can't."), ("DOT", "Then am I still at work?"),
    ("CARLA", "Technically, you're at work forever."), ("DOT", "I want to speak to my manager."), ("CARLA", "I'm your manager.")]),
dict(id="S35", act=4, lines=[("N", "Workday said the trouble started while it was testing its backup systems. Read that again. The backup test, the thing meant to protect you if something breaks, is what broke.")]),
dict(id="S36", act=4, lines=[("N", "Some systems went into maintenance mode, and the company posted updates every half hour, without giving a time it would be fixed. If your paycheck runs through one app, and that app has a bad weekend, the question isn't whether your boss owes you the money. They do. The question is whether your rent can wait for it.")]),
dict(id="S37", act=4, card="Was It Hackers?", dur=3.0),
dict(id="S38", act=4, lines=[("N", "Three huge failures. Forty-eight hours. Of course the internet said cyberattack. Even a member of Congress asked out loud whether something nefarious was going on.")]),
dict(id="S39", act=4, lines=[("MABEL", "Did you take down the airplanes?"), ("PIP", "No."), ("MABEL", "The email?"), ("PIP", "No."), ("MABEL", "Payroll?"),
    ("PIP", "I use Workday. I didn't get paid either.")]),
dict(id="S40", act=4, lines=[("N", "Every official answer so far says the same thing: no sign of an attack. The White House said there was no indication of a nefarious act. Microsoft said it found no malicious activity. And reports on Workday said it wasn't believed to be a security incident either.")]),
dict(id="S41", act=4, lines=[("N", "And here's the part I actually think is scarier. Microsoft: broke during a capacity upgrade. The F A A: broke during a copper-to-fiber upgrade. Workday: broke during a test of its backups. Nobody attacked these systems. They broke while someone was trying to make them better. That's not a villain you can arrest. That's complexity. Systems so big and so tangled, that fixing one wire can knock over a country.")]),
# ---------------- ACT 5: what the market did ----------------
dict(id="S42", act=5, card="What the Market Did", dur=3.0),
dict(id="S43", act=5, lines=[("N", "Okay. So what did Wall Street do with all this? The timing was almost comic. The ground stop hit at three fifty-four. The New York market closes at four. Six minutes."),
    ("GUS", "Airlines are falling!"), ("GUS", "Market's closed."), ("GUS", "Airlines are falling in the dark now.")]),
dict(id="S44", act=5, lines=[("N", "In those last minutes, airline shares slipped. United closed down about one point seven percent. JetBlue and Alaska fell about one point four. American, about one percent. Delta barely moved. After the bell, a few dipped further. JetBlue was down nearly four percent.")]),
dict(id="S45", act=5, lines=[("N", "And Microsoft, after two days of the world's email being broken? Its stock was basically flat on Friday."),
    ("NINA", "Their email was down for two days and their stock didn't move?"), ("WENDELL", "Their customers can't leave."), ("NINA", "Why not?"),
    ("WENDELL", "Where would you go? You'd have to email everyone your new address."), ("NINA", "Huh.")]),
dict(id="S46", act=5, lines=[("N", "That's a lesson investors have learned before. In July twenty twenty-four, a bad software update from the security company CrowdStrike crashed millions of Windows computers worldwide. CrowdStrike's stock dropped about eleven percent that day. Delta Air Lines said that outage cost it around half a billion dollars. And within about a year, CrowdStrike's stock was higher than before the crash.")]),
dict(id="S47", act=5, lines=[("N", "Markets tend to punish the companies stuck with the bill, like airlines, more than the companies that caused the problem. Because when one company runs the pipes that everyone needs, a bad week doesn't change who everyone needs.")]),
dict(id="S48", act=5, lines=[("N", "Monday the sixteenth is the first full trading day since all this. Watch three things. Airlines, which lose money on every cancelled flight and every hotel voucher. Workday, whose outage started after Friday's close, so Monday is the market's first chance to react. And the companies that might be paid to fix it.")]),
dict(id="S49", act=5, lines=[("N", "Remember the fifty billion dollars? If Congress agrees, that money flows to the companies that build radar, radios, fiber and routers. A failure like this is a disaster for travellers. For some suppliers, it's a sales pitch."),
    ("WENDELL", "What's all this?"), ("GUS", "Routers."), ("WENDELL", "All of you?"), ("GUS", "Fifty billion dollars of us.")]),
# ---------------- ACT 6: one well + wallet + ending ----------------
dict(id="S50", act=6, card="One Well, Whole Village", dur=3.0),
dict(id="S51", act=6, lines=[("N", "Here's the big idea under all three stories. Imagine a village where every family gets water from one well. It's efficient. One well is cheaper to dig, cheaper to clean, and easier to manage than a hundred. Until the day somebody drops a boot in it."),
    ("DOT", "It was a very small boot.")]),
dict(id="S52", act=6, lines=[("N", "That's modern business. A huge share of the world's offices run their email on one company. Thousands of employers run payroll through one company. The whole US sky is managed through one network. Each choice made sense on its own. Cheaper. Simpler. But together they create what engineers call a single point of failure. One boot, whole village.")]),
dict(id="S53", act=6, lines=[("N", "And it shows up in your investments too. If you own a simple index fund, the kind that holds the five hundred biggest American companies, a big slice of your money sits in just a handful of giant tech firms. Including the one whose email went down this week."),
    ("DAD", "I'm diversified. I own five hundred companies."), ("JIMMY", "Dad, a huge chunk of your pie is like ten of them."),
    ("DAD", "It's a very big slice."), ("JIMMY", "That's the point.")]),
dict(id="S54", act=6, lines=[("N", "That isn't a reason to panic. These companies are huge for a reason. It's just worth knowing that diversified, and spread out, aren't always the same thing.")]),
dict(id="S55", act=6, card="Your Wallet", sub="Four Questions", dur=3.0),
dict(id="S56", act=6, lines=[("N", "So what do you actually do with this? Four questions. One. If your paycheck arrived a week late, could you still pay rent? A small cash cushion, even a few hundred dollars, turns a payroll outage from a crisis into an annoyance.")]),
dict(id="S57", act=6, lines=[("N", "Two. If your flight gets cancelled, do you know your rights? In the US, if an airline cancels your flight and you choose not to travel, you're entitled to a cash refund, not just a voucher. Ask for it.")]),
dict(id="S58", act=6, lines=[("N", "Three. Run a business? Where does it all live? If your email, your files and your invoices all sit with one provider, write down what you'd do for two days without it. Nina's fax-machine uncle is not a plan. Four. Look inside your index fund. Find out how much of it is in the top five or ten companies. You might be happy with the answer. You should still know it.")]),
dict(id="S59", act=6, lines=[("N", "Let's check in one last time. Nina's email is back. She's sending two days of invoices at once, and buying a backup laptop. Carla is still waiting for the app to come back, and checking her bank account every hour. And Jimmy?")]),
dict(id="S60", act=6, lines=[("SISTER", "You're two hours late."), ("JIMMY", "I took a bus. Two trains. And a man named Gary's minivan."),
    ("SISTER", "Did you bring the rings?"), ("JIMMY", "I brought the rings.")]),
dict(id="S61", act=6, lines=[("N", "Three systems broke in forty-eight hours. Not because anyone attacked them, but because we built them to be so big, and so shared, that one small mistake travels everywhere at once. The machines will get fixed. The question is whether you've built a little backup of your own, before the board flips again.")]),
dict(id="S62", act=6, lines=[("N", "Now I want to hear from you. Did any of these outages hit you this week? A cancelled flight, a dead inbox, a missing paycheck? Tell me in the comments.")]),
dict(id="S99", act=6, card="", dur=5.5),
]
